def solve(s: str) -> str:
    if not s:
        return s

    contains_letter = any(c.isalpha() for c in s)
    if not contains_letter:
        return s[::-1]

    result = []
    for char in s:
        if char.isalpha():
            result.append(char.swapcase())
        else:
            result.append(char)
    return ''.join(result)
