from typing import Union

def is_prime(n: int) -> bool:
    """Check if a number is prime."""
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    max_divisor = int(n**0.5) + 1
    for d in range(3, max_divisor, 2):
        if n % d == 0:
            return False
    return True

def prime_length(string: Union[str, bytes, bytearray]) -> bool:
    """Check if the length of a string is a prime number."""
    if not isinstance(string, (str, bytes, bytearray)):
        raise TypeError("Input must be a string or bytes-like object")
    return is_prime(len(string))

# Example usage
print(prime_length('Hello'))  # True
print(prime_length('abcdcba'))  # True
print(prime_length('kittens'))  # True
print(prime_length('orange'))  # False
```

