from typing import List

def max_fill(grid: List[List[int]], capacity: int) -> int:
    if not grid or not grid[0] or capacity <= 0:
        return 0

    total = 0
    for row in grid:
        water = sum(row)
        if water > 0:
            total += math.ceil(water / capacity)

    return total
