def encrypt(s: str) -> str:
    import string
    rotation = 2 * 2
    lower_alphabet = string.ascii_lowercase
    upper_alphabet = string.ascii_uppercase
    encrypted = []

    for char in s:
        if char in lower_alphabet:
            new_index = (lower_alphabet.index(char) + rotation) % 26
            encrypted.append(lower_alphabet[new_index])
        elif char in upper_alphabet:
            new_index = (upper_alphabet.index(char) + rotation) % 26
            encrypted.append(upper_alphabet[new_index])
        else:
            encrypted.append(char)

    return ''.join(encrypted)
