def next_smallest(lst: List[int]) -> Optional[int]:
    if len(lst) < 2:
        return None
    first, second = math.inf, math.inf
    for number in lst:
        if number < first:
            first, second = number, first
        elif first < number < second:
            second = number
    return second if second != math.inf else None

