from typing import List

def move_one_ball(arr: List[int]) -> bool:
    if not arr:
        return True

    n = len(arr)
    sorted_arr = sorted(arr)

    for shift in range(n):
        shifted_arr = arr[-shift:] + arr[:-shift]
        if shifted_arr == sorted_arr:
            return True

    return False
