def modp(n: int, p: int) -> int:
    if p == 1:
        return 0
    if n == 0:
        return 1
    if n < 0:
        return pow(2, n, p)
    result = 1
    base = 2
    while n > 0:
        if n % 2 == 1:
            result = (result * base) % p
        base = (base * base) % p
        n //= 2
    return result
```

