            return False
    return True

def is_multiply_prime(a: int) -> bool:
    """Check if a number is the multiplication of 3 prime numbers."""
    if a < 2:
        return False
    for i in range(2, a):
        if is_prime(i):
            for j in range(2, a // i + 1):
                if is_prime(j):
                    if a % (i * j) == 0 and is_prime(a // (i * j)):
                        return True
    return False

def main():
