from typing import List

def is_palindrome(s: str) -> bool:
    return s == s[::-1]

def make_palindrome(s: str) -> str:
    if not s:
        return s
    for i in range(len(s)):
        if is_palindrome(s[i:]):
            return s + s[:i][::-1]
    return s + s[::-1]

