from typing import List

def parse_music(music_string: str) -> List[int]:
    if not music_string:
        return []

    notes = music_string.split()
    beats = []

    for note in notes:
        if note == 'o':
            beats.append(4)
        elif note == 'o|':
            beats.append(2)
        elif note == '.|':
            beats.append(1)
        else:
            raise ValueError(f"Invalid note: {note}")

    return beats
```

