    char_count: Dict[str, int] = {}
    for char in string.lower():
        if char not in char_count:
            char_count[char] = 1
    return len(char_count)

def main():
    print(count_distinct_characters('xyzXYZ'))  # 3
    print(count_distinct_characters('Jerry'))  # 5

if __name__ == "__main__":
    main()
```

