def choose_num(x, y):
    if not isinstance(x, int) or not isinstance(y, int):
        raise TypeError("Both x and y must be integers")
    if x < 0 or y < 0:
        raise ValueError("Both x and y must be positive numbers")
    if x > y:
        return -1
    return max((i for i in range(x, y + 1) if i % 2 == 0), default=-1)
